<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import QRCode from 'qrcode'
import {MapPin,Clock,ShieldCheck,ArrowLeft,CheckCircle,Copy,AlertCircle} from 'lucide-vue-next'
import {api,post,session,labels,date,pickupCode,type Batch} from '../api'
const route=useRoute(),router=useRouter(),batch=ref<Batch|null>(null),privateInfo=ref<Record<string,string>|null>(null),journey=ref<Batch|null>(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),token=ref(''),qr=ref(''),entry=ref(''),weight=ref<number|undefined>(),reason=ref(''),events=ref<{id:string;kind:string;created_at:string}[]>([]),proof=ref<Record<string,unknown>[]>([]),showDispute=ref(false)
const eligible=computed(()=>session.organizations.find(o=>o.kind==='recipient'&&o.status==='approved'))
const cid=computed(()=>journey.value?.claim_id)
const isDonor=computed(()=>journey.value?.is_donor)
const eventLabels:Record<string,string>={'batch.created':'商家发布食品','batch.cancelled':'商家取消批次','claim.created':'社区组织认领','claim.cancelled':'接收方取消认领','handover.donor_confirmed':'商家确认交出','handover.completed':'接收方确认收到','dispute.opened':'已发起争议','dispute.resolved':'争议已处理'}
async function load(){if(loading.value)return;loading.value=true;error.value='';try{const r=await api<{batch:Batch;private:Record<string,string>|null}>(`/batches/${route.params.id}`);batch.value=r.batch;privateInfo.value=r.private;const d=await api<{batches:Batch[]}>('/dashboard');journey.value=d.batches.find(b=>b.id===route.params.id)||null;if(journey.value){const [e,p]=await Promise.all([api<{items:typeof events.value}>(`/batches/${route.params.id}/events`),api<{items:typeof proof.value}>(`/batches/${route.params.id}/proof`)]);events.value=e.items;proof.value=p.items}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(load)
async function action(path:string,body:unknown,success:string){if(busy.value)return;busy.value=true;error.value='';try{await post(path,body);notice.value=success;token.value='';qr.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function claim(){if(!eligible.value)return;await action(`/batches/${route.params.id}/claims`,{organization_id:eligible.value.id},'认领成功。你现在可以查看详细领取地址并生成领取码。')}
async function generate(){if(!cid.value||busy.value)return;busy.value=true;error.value='';try{const r=await post<{pickup_token:string;expires_at:string}>(`/claims/${cid.value}/pickup-token`);token.value=r.pickup_token;qr.value=await QRCode.toDataURL(JSON.stringify({claim_id:cid.value,token:token.value}),{margin:1,width:220,color:{dark:'#244b39',light:'#ffffff'}});notice.value=`领取码有效至 ${date(r.expires_at)}。重新生成会让旧码失效。`}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function copy(){try{await navigator.clipboard.writeText(token.value);notice.value='领取码已复制，请只交给对应商家。'}catch{error.value='复制失败，请手动选择下方领取码。'}}
function downloadProof(){const blob=new Blob([JSON.stringify(proof.value,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=`rescueproof-${route.params.id}-proof.json`;a.click();URL.revokeObjectURL(u)}
</script>
<template><section class="container page-section"><button class="text-button back-link" @click="router.back()"><ArrowLeft :size="16"/>返回</button><div v-if="loading" class="empty-state">正在读取食品详情…</div><template v-else><p v-if="error" class="error" role="alert">{{error}} <RouterLink v-if="!session.user" to="/login">去登录</RouterLink><button v-else @click="load">刷新</button></p><p v-if="notice" class="success" role="status">{{notice}}</p><div v-if="batch" class="detail-layout"><div><div class="surface detail-main"><div class="eyebrow">{{batch.donor_name}} · {{labels[batch.category]}}</div><div class="detail-title"><h1>{{batch.title}}</h1><span class="status" :class="batch.status">{{labels[batch.status]}}</span></div><div class="detail-quantity">{{batch.quantity}} <span>{{labels[batch.unit]}} / 预计 {{batch.weight_kg}} kg</span></div><dl class="detail-facts"><div><dt><MapPin :size="17"/> 所在地区</dt><dd>{{batch.area}}</dd></div><div><dt><Clock :size="17"/> 可领取时段</dt><dd>{{date(batch.pickup_start)}} — {{date(batch.pickup_end)}}</dd></div><div><dt>食品到期</dt><dd>{{date(batch.expires_at)}}</dd></div></dl><template v-if="privateInfo"><h3>交接信息</h3><dl class="detail-facts"><div><dt>取货地址</dt><dd>{{privateInfo.pickup_address}}</dd></div><div><dt>联系人</dt><dd>{{privateInfo.contact}}</dd></div><div><dt>储存要求</dt><dd>{{privateInfo.storage_notes}}</dd></div><div><dt>过敏原</dt><dd>{{privateInfo.allergens}}</dd></div></dl></template><p v-else class="info-note"><ShieldCheck :size="18"/>详细地址和联系方式仅向成功认领的组织开放。</p></div><div v-if="events.length" class="surface timeline-panel"><h2>每一份善意，都有迹可循。</h2><div v-for="e in events" :key="e.id" class="timeline-item"><CheckCircle :size="18"/><div><strong>{{eventLabels[e.kind]||e.kind}}</strong><small>{{date(e.created_at)}}</small></div></div></div><div v-if="journey" class="surface proof-panel"><h3><ShieldCheck :size="20"/>交接记录核验</h3><p v-if="!proof.length">记录正在等待后台汇总，尚未锚定。</p><template v-else><div v-for="p in proof" :key="String(p.event_id)" class="proof-row"><span>{{p.status==='confirmed'?'已上链核验':p.status==='submitted'?'链上交易待确认':'摘要已生成，待上链'}}</span><code>{{String(p.root).slice(0,20)}}…</code></div><button class="text-button" @click="downloadProof">下载完整核验凭据</button></template><p class="form-hint">凭据证明数据完整性，不代表食品安全认证。争议和后续修正也会保留记录。</p></div></div><aside class="surface action-panel"><h2>一起，接住这份好食物。</h2><p>确认你能在约定时段安全取货，认领后请按时前往。</p><template v-if="batch.status==='open'&&!journey"><button v-if="eligible" class="button full" :disabled="busy" @click="claim">{{busy?'处理中…':'认领这批食品'}}</button><div v-else class="info-note">需要已审核的社区接收组织身份才能认领。<RouterLink to="/workspace">查看组织状态</RouterLink></div></template><template v-if="cid"><template v-if="!isDonor&&batch.status==='claimed'"><button class="button full" :disabled="busy" @click="generate">{{busy?'生成中…':'生成 / 更新领取码'}}</button><div v-if="qr" class="qr-panel"><img :src="qr" alt="交接领取二维码"/><code>{{token}}</code><button class="text-button" @click="copy"><Copy :size="15"/>复制领取码</button><p>请向对应商家出示，不要公开分享。</p></div><button class="text-button danger" :disabled="busy" @click="action(`/claims/${cid}/cancel`,{},'已取消认领。')">取消本次认领</button></template><form v-if="isDonor&&batch.status==='claimed'" @submit.prevent="action(`/claims/${cid}/handover`,{pickup_token:pickupCode(entry)},'已确认交出，等待接收组织确认。')"><label>接收方出示的领取码<textarea v-model="entry" required placeholder="输入 64 位领取码，或粘贴二维码解码后的内容"></textarea></label><button class="button full" :disabled="busy">确认已交出食品</button></form><form v-if="!isDonor&&batch.status==='handed_over'" @submit.prevent="action(`/claims/${cid}/receipt`,{actual_weight_kg:weight??null},'交接已完成，感谢你接住这份食物。')"><label>实际接收重量 (kg，可留空)<input v-model.number="weight" type="number" min="0" max="100000" step="0.001" placeholder="未称重可不填"/></label><p class="form-hint">只有实际填报重量计入重量指标。请先检查数量与包装。</p><button class="button full" :disabled="busy">确认已收到食品</button></form><p v-if="isDonor&&batch.status==='handed_over'" class="info-note">已确认交出，正在等待接收方确认收到。</p><template v-if="['claimed','handed_over','completed'].includes(batch.status)"><button class="text-button danger" @click="showDispute=!showDispute"><AlertCircle :size="16"/>交接有问题？发起争议</button><form v-if="showDispute" @submit.prevent="action(`/claims/${cid}/disputes`,{reason},'争议已提交，运营人员将跟进。')"><label>问题说明<textarea v-model="reason" required minlength="5" maxlength="1000" placeholder="说明数量、时间或交接方面的问题"></textarea></label><button class="button secondary full" :disabled="busy">提交争议</button></form></template></template><button v-if="isDonor&&batch.status==='open'" class="text-button danger" :disabled="busy" @click="action(`/batches/${batch.id}/cancel`,{},'食品批次已取消。')">取消发布</button><div class="action-safety"><ShieldCheck :size="24"/><p>交接时请核对食品状态、过敏原与保存要求。平台记录不替代现场检查。</p></div></aside></div></template></section></template>
